changeSet.sql:
WITH ranked AS ( SELECT RESULT_ID, ROW_NUMBER() OVER ( PARTITION BY STRATEGY_ID, STRATEGY_VID ORDER BY CREATED_AT ASC, RESULT_ID ) AS vid, ROW_NUMBER() OVER ( PARTITION BY STRATEGY_ID, STRATEGY_VID ORDER BY CREATED_AT DESC, RESULT_ID ) AS rev_rank FROM BT.RESULT WHERE STRATEGY_ID IS NOT NULL ) UPDATE BT.RESULT R SET RESULT_VID = ranked.vid, IS_CURRENT_IND = CASE WHEN ranked.rev_rank = 1 THEN 'Y' ELSE 'N' END FROM ranked WHERE R.RESULT_ID = ranked.RESULT_ID;
UPDATE BT.RESULT SET RESULT_VID = 1, IS_CURRENT_IND = 'Y' WHERE RESULT_VID IS NULL;
ALTER TABLE BT.RESULT ALTER COLUMN RESULT_VID SET NOT NULL; ALTER TABLE BT.RESULT ALTER COLUMN IS_CURRENT_IND SET NOT NULL;

CREATE INDEX IF NOT EXISTS IX_RESULT_STRATEGY_CURRENT
    ON BT.RESULT (STRATEGY_ID, STRATEGY_VID)
    WHERE IS_CURRENT_IND = 'Y';
